typedef struct {
    int quot;
    int rem;
  } div_t;

struct ht {
    ht_entry* entries;
    size_t capacity;
    size_t length;
};

typedef struct {
    const char* key;
    void* value;
} ht_entry;

typedef struct {
    const char* key;
    void* value;
    ht* _table;
    size_t _index;
} hti;

typedef struct {
    long int quot;
    long int rem;
  } ldiv_t;

__extension__ typedef struct {
    long long int quot;
    long long int rem;
  } lldiv_t;

ht* ht_create(void) {
    ht* table = malloc(sizeof(ht));
    if (table == ((void*)0)) {
        return ((void*)0);
    }
    table->length = 0;
    table->capacity = 16;
    table->entries = calloc(table->capacity, sizeof(ht_entry));
    if (table->entries == ((void*)0)) {
        free(table);
        return ((void*)0);
    }
    return table;
}

void ht_destroy(ht* table) {
    for (size_t i = 0; i < table->capacity; i++) {
        free((void*)table->entries[i].key);
    }
    free(table->entries);
    free(table);
}

void* ht_get(ht* table, const char* key) {
    uint64_t hash = hash_key(key);
    size_t index = (size_t)(hash & (uint64_t)(table->capacity - 1));
    while (table->entries[index].key != ((void*)0)) {
        if (strcmp(key, table->entries[index].key) == 0) {
            return table->entries[index].value;
        }
        index++;
        if (index >= table->capacity) {
            index = 0;
        }
    }
    return ((void*)0);
}

const char* ht_set(ht* table, const char* key, void* value) {
    ((value != ((void*)0)) ? (void) (0) : __assert_fail ("value != NULL", "ht.c", 154, __extension__ __PRETTY_FUNCTION__));
    if (value == ((void*)0)) {
        return ((void*)0);
    }
    if (table->length >= table->capacity / 2) {
        if (!ht_expand(table)) {
            return ((void*)0);
        }
    }
    return ht_set_entry(table->entries, table->capacity, key, value, &table->length);
}

hti ht_iterator(ht* table) {
    hti it;
    it._table = table;
    it._index = 0;
    return it;
}

_Bool ht_next(hti* it) {
    ht* table = it->_table;
    while (it->_index < table->capacity) {
        size_t i = it->_index;
        it->_index++;
        if (table->entries[i].key != ((void*)0)) {
            ht_entry entry = table->entries[i];
            it->key = entry.key;
            it->value = entry.value;
            return 1;
        }
    }
    return 0;
}

static uint64_t hash_key(const char* key) {
    uint64_t hash = 14695981039346656037UL;
    for (const char* p = key; *p; p++) {
        hash ^= (uint64_t)(unsigned char)(*p);
        hash *= 1099511628211UL;
    }
    return hash;
}

static const char* ht_set_entry(ht_entry* entries, size_t capacity, const char* key, void* value, size_t* plength) {
    uint64_t hash = hash_key(key);
    size_t index = (size_t)(hash & (uint64_t)(capacity - 1));
    while (entries[index].key != ((void*)0)) {
        if (strcmp(key, entries[index].key) == 0) {
            entries[index].value = value;
            return entries[index].key;
        }
        index++;
        if (index >= capacity) {
            index = 0;
        }
    }
    if (plength != ((void*)0)) {
        key = strdup(key);
        if (key == ((void*)0)) {
            return ((void*)0);
        }
        (*plength)++;
    }
    entries[index].key = (char*)key;
    entries[index].value = value;
    return key;
}

static _Bool ht_expand(ht* table) {
    size_t new_capacity = table->capacity * 2;
    if (new_capacity < table->capacity) {
        return 0;
    }
    ht_entry* new_entries = calloc(new_capacity, sizeof(ht_entry));
    if (new_entries == ((void*)0)) {
        return 0;
    }
    for (size_t i = 0; i < table->capacity; i++) {
        ht_entry entry = table->entries[i];
        if (entry.key != ((void*)0)) {
            ht_set_entry(new_entries, new_capacity, entry.key, entry.value, ((void*)0));
        }
    }
    free(table->entries);
    table->entries = new_entries;
    table->capacity = new_capacity;
    return 1;
}
